INSERT INTO resy_experiences (id, name, short_description, long_description, image_url, is_external, external_url, reservation_type, price, show_price, display_order, is_active, location_id, show_waitlist, points_earned, created_at, updated_at) VALUES (E'9259bec6-b134-4b04-a5c2-f60c2c367956', E'Wine Tasting at the Winery Tasting Bar', E'Formal Tasting Room\nIn our seated indoor tasting room, one of our Estate Hosts will guide you through an unforgettable experience.\n', E'Formal Tasting Room\nIn our seated indoor tasting room, one of our Estate Hosts will guide you through an unforgettable experience.\n\nTastings: $16 per person\n\nIncludes 8 tokens and a commemorative Nashoba wine glass\n\nTokens may be used for any of our products crafted on-site\n\nWine, Beer & Hard Cider: 1 token each\n\nDistilled Spirits: 2 tokens each\n\nThis experience lasts approximately 45 minutes, giving you time to mix and match your selections at your own pace. To complement your tasting, cheese boards are available for purchase.\n\nReservations:\n\nStrongly recommended on weekends\n\nHeld for a maximum of 10 minutes before being forfeited\n\nNon-refundable and cannot be rescheduled\n\nGoal of the Experience:\nOur Formal Tasting Room is designed for guests who want to learn about our wines and operations while sampling. Unlike the Pavilion Tasting area, which emphasizes casual conversation, this guided session focuses on education and exploration. Please manage your time to complete your tasting wi', E'/api/media-library/4b0e8a49-33bd-4fb3-8fdb-40891e3dcb1e/file', false, E'https://tables.toasttab.com/restaurants/f6a9a99b-0a3a-4a5b-904f-c8c82a46d793/reserve?partySize=2&dateTime=2025-12-17T11:00:00.000-05:00', E'ticketed', E'16.00', false, 0, true, E'66fd6924-1bfb-426b-955d-168be80ddd63', false, 0, '2025-11-20T12:10:42.875Z', '2025-12-06T14:42:20.794Z');
INSERT INTO resy_experiences (id, name, short_description, long_description, image_url, primary_image_key, is_external, external_url, show_price, display_order, is_active, location, show_waitlist, points_earned, created_at, updated_at) VALUES (E'0f28e907-08d0-439c-b384-949c7612f532', E'J''s Restaurant', E'Award-winning farm-to-table dining experience in our elegant restaurant.', E'J''s Restaurant offers an exceptional farm-to-table dining experience featuring seasonal ingredients from our orchards and local farms. Our chef-crafted menu showcases the best of New England cuisine paired with our award-winning wines. Reservations managed through OpenTable.', E'/api/media-library/c693f47b-a12d-4d61-8026-321cb86f42d3/file', E'/objects/uploads/fbd16716-8b38-4c92-908d-e573d0e00cf8', true, E'https://www.opentable.com/booking/restref/availability?rid=231097&lang=en-US&color=1&r3uid=cfe&dark=false&correlationId=f0b562f6-da9c-4c60-b6ef-71a7c3bdcbce&restRef=231097&partySize=4&dateTime=2025-05-17T19%3A00&otSource=Restaurant%20website', true, 1, true, E'Bolton, MA', false, 0, '2025-11-18T18:31:43.954Z', '2025-12-06T03:06:55.685Z');
