INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, primary_image_key, is_external, external_url, reservation_type, show_price, display_order, is_active, show_waitlist, points_earned, created_at, updated_at) VALUES (E'7b3dcc5f-3b47-4e6b-8244-4987293b8097', E'Pavilion Tastings', E'Outdoor tasting experience at our scenic pavilion overlooking the vineyard.', E'Pavilion Tasting', E'', E'/@fs/home/runner/workspace/attached_assets/generated_images/Outdoor_pavilion_tasting_5f38a008.png', E'/objects/uploads/afaea93d-a9b9-46ba-8e5f-7050128e0a33', false, E'', E'table', true, 4, false, false, 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:50:33.540Z');
INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, primary_image_key, is_external, external_url, reservation_type, show_price, display_order, is_active, show_waitlist, points_earned, created_at, updated_at) VALUES (E'fd589420-3c4f-4c93-b1e8-069c66db7516', E'The Knoll Restaurant', E'Casual dining with spectacular views and locally-sourced ingredients.', E'', E'', E'/@fs/home/runner/workspace/attached_assets/generated_images/Knoll_outdoor_dining_vista_a227d3e7.png', E'/objects/uploads/ae524e27-6107-4fec-9a06-65f44d10cb97', false, E'', E'table', true, 5, false, false, 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:50:44.066Z');
INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, is_external, external_url, reservation_type, price, show_price, display_order, is_active, location_id, show_waitlist, points_earned, created_at, updated_at) VALUES (E'dfec79db-db48-475d-8779-d6179ba37f57', E'Winery Tours', E'Behind-the-scenes tour of our winery, distillery and brewery with tastings included.', E'', E'', E'/api/media-library/6270bf85-6a5b-47a7-96d5-59adb87a0d15/file', false, E'', E'ticketed', E'16.00', true, 3, true, E'08b02d64-21f2-4df8-941d-af98dc51fc08', false, 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:59:39.117Z');
INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, primary_image_key, is_external, external_url, reservation_type, show_price, display_order, is_active, location_id, show_waitlist, closed_message, fully_booked_message, private_event_message, points_earned, created_at, updated_at) VALUES (E'693ed83c-e010-496b-8cfd-f145c86da742', E'Pavilion Seating', E'Reserve a table at our outdoor pavilion for wine, beer, and light fare.', E'', E'You are making a reservation for a Table at The Knoll which is an Outdoor Restaurant without any Indoor seating.\n\nReservations are available up to 30 days in advance and close at 7:00 AM each day for same-day bookings.\nAfter 7:00 AM, reservations for that day can no longer be made.\n\nWe welcome walk-ins throughout the day, as we are almost never fully booked. There may be a short wait during busy times.\n\nGroup Sizes\nMaximum reservation size: 14 guests (adults, children, and babies included)\n\nGroups larger than 14 must be booked as a private event.\n\nWe do not combine tables, reserve specific tables, or seat multiple reservations together.\n\nOutdoor seating is first come, first served — reservations are not available during the off-season.  All outdoor tables have umbrellas.\n\nAccessibility & Food Policy\nIf you need an accessible table, please make a reservation and then email support@nashobawinery.com with your name, date, and time — we’ll ensure you are seated appropriately.\n', E'/@fs/home/runner/workspace/attached_assets/generated_images/Pavilion_event_seating_6daeb5b9.png', E'/objects/uploads/0fd4e3ea-ed66-4f7d-b3a2-75f6b95508d6', false, E'', E'table', true, 1, false, E'a82604d4-0f32-43b4-ad04-28e2bf92456c', false, E'We are currently closed. Please check back during our operating hours.', E'All reservations are fully booked for this date. Please try another date or join our waitlist.', E'This location is reserved for a private event. We apologize for the inconvenience.', 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:50:02.672Z');
